def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    comparisons = {
        "2019": v1 < 150000,
        "2018": v2 < 150000,
    }

    matching_years = [year for year, is_match in comparisons.items() if is_match]

    return {
        "value": matching_years[0] if len(matching_years) == 1 else matching_years,
        "trace": {
            "threshold": 150000,
            "comparisons": comparisons,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None,
            },
        },
    }
